from collections import deque


def minimum_moves(grid):
    n = len(grid)

    def is_clear(r, c):
        return 0 <= r < n and 0 <= c < n and grid[r][c] == 0

    start = (0, 0, 0)
    target = (n - 1, n - 2, 0)
    if start == target:
        return 0

    visited = {start}
    queue = deque([(0, 0, 0, 0)])

    while queue:
        r, c, orient, d = queue.popleft()
        candidates = []
        if orient == 0:
            if is_clear(r, c + 2):
                candidates.append((r, c + 1, 0))
            if is_clear(r + 1, c) and is_clear(r + 1, c + 1):
                candidates.append((r + 1, c, 0))
                candidates.append((r, c, 1))
        else:
            if is_clear(r + 2, c):
                candidates.append((r + 1, c, 1))
            if is_clear(r, c + 1) and is_clear(r + 1, c + 1):
                candidates.append((r, c + 1, 1))
                candidates.append((r, c, 0))

        for state in candidates:
            if state in visited:
                continue
            visited.add(state)
            if state == target:
                return d + 1
            queue.append((state[0], state[1], state[2], d + 1))

    return -1


if __name__ == "__main__":
    print(minimum_moves([[0, 0, 0], [0, 0, 0], [0, 0, 0]]))
    print(minimum_moves([[0, 0, 0], [0, 0, 0], [0, 1, 1]]))

