import java.util.*;

public class Main {
    static int minimumMoves(int[][] grid) {
        int n = grid.length;
        boolean[][][] visited = new boolean[n][n][2];
        visited[0][0][0] = true;
        if (n - 1 == 0 && n - 2 == 0) return 0;

        Queue<int[]> queue = new LinkedList<>();
        queue.add(new int[]{0, 0, 0, 0});

        while (!queue.isEmpty()) {
            int[] cur = queue.poll();
            int r = cur[0], c = cur[1], orient = cur[2], d = cur[3];
            List<int[]> candidates = new ArrayList<>();

            if (orient == 0) {
                if (isClear(grid, n, r, c + 2)) candidates.add(new int[]{r, c + 1, 0});
                if (isClear(grid, n, r + 1, c) && isClear(grid, n, r + 1, c + 1)) {
                    candidates.add(new int[]{r + 1, c, 0});
                    candidates.add(new int[]{r, c, 1});
                }
            } else {
                if (isClear(grid, n, r + 2, c)) candidates.add(new int[]{r + 1, c, 1});
                if (isClear(grid, n, r, c + 1) && isClear(grid, n, r + 1, c + 1)) {
                    candidates.add(new int[]{r, c + 1, 1});
                    candidates.add(new int[]{r, c, 0});
                }
            }

            for (int[] s : candidates) {
                if (visited[s[0]][s[1]][s[2]]) continue;
                visited[s[0]][s[1]][s[2]] = true;
                if (s[0] == n - 1 && s[1] == n - 2 && s[2] == 0) return d + 1;
                queue.add(new int[]{s[0], s[1], s[2], d + 1});
            }
        }
        return -1;
    }

    static boolean isClear(int[][] grid, int n, int r, int c) {
        return r >= 0 && r < n && c >= 0 && c < n && grid[r][c] == 0;
    }

    public static void main(String[] args) {
        System.out.println(minimumMoves(new int[][]{{0, 0, 0}, {0, 0, 0}, {0, 0, 0}}));
        System.out.println(minimumMoves(new int[][]{{0, 0, 0}, {0, 0, 0}, {0, 1, 1}}));
    }
}

